const message = $input.first().json.message;
const text = message.text || '';
const userId = message.from.id;
const userName = `${message.from.first_name} ${message.from.last_name || ''}`.trim();

// Enhanced input detection
const inputType = {
  isCommand: text.startsWith('/'),
  isPhoto: message.photo !== undefined,
  isVoice: message.voice !== undefined,
  isText: text && !text.startsWith('/'),
};

// Command parsing
let command = null;
if (inputType.isCommand) {
  command = text.split(' ')[0].toLowerCase();
}

// User context setup
const userContext = {
  id: userId,
  name: userName,
  username: message.from.username || '',
  chatId: message.chat.id,
  timestamp: new Date().toISOString()
};

return {
  json: {
    ...userContext,
    inputType,
    command,
    originalMessage: message,
    processingId: `proc_${userId}_${Date.now()}`
  }
};

const item = JSON.parse(JSON.stringify($input.item));

// Check if we have binary data
if (item.binary && item.binary.data) {
  // Fix the MIME type
  item.binary.data.mimeType = 'image/jpeg';

  // If the file has a .jpg or .jpeg extension
  if (item.binary.data.fileName.endsWith('.jpg') || item.binary.data.fileName.endsWith('.jpeg')) {
    item.binary.data.mimeType = 'image/jpeg';
  }
  // If the file has a .png extension
  else if (item.binary.data.fileName.endsWith('.png')) {
    item.binary.data.mimeType = 'image/png';
  }
}

return {json: item.json, binary: item.binary};

